// ── Run ────────────────────────────────────────────────────────────────────────
const HTML_PATH = path.resolve(process.cwd(), 'index.html');
let html = fs.readFileSync(HTML_PATH, 'utf8');

let fixed = 0;
let skipped = 0;

for (const [srcName, {ti, de}] of Object.entries(TRANS)) {
  // Only fix if title is NOT already Arabic (no Arabic chars)
  const escaped = srcName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Pattern: "ti":"<english>","de":"وصفة ... : srcName" → replace both
  const regex = new RegExp(`("ti":")(${escaped})("(?:.*?"de":")[^"]*")`, 'g');

  // Simpler approach: find the recipe by src_name and replace ti + de + seo_title + seo_desc
  const beforeCount = html.split(`"ti":"${srcName}"`).length - 1;
  if (beforeCount > 0) {
    // Replace English ti with Arabic
    html = html.replaceAll(`"ti":"${srcName}"`, `"ti":"${ti}"`);
    // Replace generic seo_title
    html = html.replaceAll(`"seo_title":"وصفة ${srcName} | مطبخ 360"`, `"seo_title":"وصفة ${ti} | مطبخ 360"`);
    html = html.replaceAll(`"seo_desc":"وصفة.*? تقليدية: ${srcName}"`, `"seo_desc":"${de}"`);
    // Replace generic de
    const dePatterns = [
      `وصفة مغربي تقليدية: ${srcName}`,
      `وصفة مصري تقليدية: ${srcName}`,
      `وصفة إيطالي تقليدية: ${srcName}`,
      `وصفة ياباني تقليدية: ${srcName}`,
      `وصفة هندي تقليدية: ${srcName}`,
      `وصفة صيني تقليدية: ${srcName}`,
      `وصفة فرنسي تقليدية: ${srcName}`,
      `وصفة أمريكي تقليدية: ${srcName}`,
      `وصفة بريطاني تقليدية: ${srcName}`,
      `وصفة تقليدية: ${srcName}`,
    ];
    for (const p of dePatterns) {
      if (html.includes(p)) {
        html = html.replaceAll(p, de);
      }
    }
    fixed += beforeCount;
    console.log(`✓ ${srcName} → ${ti}`);
  } else {
    skipped++;
  }
}

fs.writeFileSync(HTML_PATH, html);
console.log(`\n✅ ${fixed} titres corrigés | ${skipped} non trouvés`);
